import { Effect } from "effect";
import type { AssayFeed } from "./assay-feed.js";

/** The sampled count describes the first read; labels describe the later complete read. */
export const loadBatchDisplay = Effect.fn("loadBatchDisplay")(function* (
  feed: AssayFeed,
  batchId: string,
) {
  const sampled = yield* feed.currentlyAnalyzing(batchId);
  const records = yield* feed.batchRecords(batchId);
  return {
    sampledAnalyzing: sampled.length,
    pendingLabels: records.filter(({ verdict }) => verdict === null).map(({ id }) => id),
  };
});

import { Effect, Schema } from "effect";

/** A missing verdict remains pending, including when lifecycle is null. */
const PendingAssay = Schema.Struct({
  id: Schema.String,
  lifecycle: Schema.NullOr(Schema.Literals(["submitted", "analyzing"])),
  verdict: Schema.Null,
});

/** A final verdict settles an assay even when lifecycle is null. */
const FinishedAssay = Schema.Struct({
  id: Schema.String,
  lifecycle: Schema.NullOr(Schema.Literal("archived")),
  verdict: Schema.Literals(["passed", "rejected"]),
});

export const AssayRecord = Schema.Union([PendingAssay, FinishedAssay]);
export type AssayRecord = typeof AssayRecord.Type;

export interface AssayFeed {
  /** All analyzing assays for this batch at the instant this call reads. */
  readonly currentlyAnalyzing: (batchId: string) => Effect.Effect<ReadonlyArray<AssayRecord>>;
  /** Every assay in the batch at this call's own instant; the calls share no snapshot. */
  readonly batchRecords: (batchId: string) => Effect.Effect<ReadonlyArray<AssayRecord>>;
}

import { Effect } from "effect";
import type { AssayFeed } from "./assay-feed.js";

/** The sampled count describes the first read; labels describe the later complete read. */
export const loadBatchDisplay = Effect.fn("loadBatchDisplay")(function* (
  feed: AssayFeed,
  batchId: string,
) {
  const sampled = yield* feed.currentlyAnalyzing(batchId);
  const sampledIds = new Set(sampled.map(({ id }) => id));
  const records = yield* feed.batchRecords(batchId);
  return {
    sampledAnalyzing: sampled.length,
    pendingLabels: records
      .filter(
        ({ id, lifecycle, verdict }) =>
          verdict === null && (lifecycle !== "analyzing" || sampledIds.has(id)),
      )
      .map(({ id }) => id),
  };
});

